const input = $input.first().json;

const activeActuators = (input.actuators ?? []).filter(a => a.skipped === false && a.re_evaluation.skipped===false);

const actuators = activeActuators.length === 0 ? null : activeActuators.map(a => ({
  type:           a.type,
  status:         a.status ?? null,
  classification: a.classification ?? null,
  ...(a.control_mode === 'semi-auto' ? { recommended_action: a.recommended_action ?? null } : {}),
  run:            a.run            ?? null,
  re_evaluation:  a.re_evaluation  ?? null
}));

const output = {
  adr: $input.first().json.meta.adr,
  sensors: (input.sensors ?? []).map(s => ({
    type:        s.type,
    description: s.description ?? null
  })),
  actuators,
  notifications:  input.notifications  ?? null,
  warnings:       input.warnings       ?? null,
  recommendation: input.recommendation ?? null,
  weather:        input.weather        ?? null
};

return [{ json: output }];

// ─── 0. Get input from n8n ─────────────────────────────────────────────────────
const input = $input.first().json;
const entities = [];

// ─── Helper: convert "HH:MM" to full ISO datetime using today's date ──────────
function toFullDatetime(timeStr) {
  if (!timeStr) return null;
  if (timeStr.includes('T') || timeStr.length > 5) return timeStr;
  const now = new Date();
  const yyyy = now.getFullYear();
  const mm   = String(now.getMonth() + 1).padStart(2, '0');
  const dd   = String(now.getDate()).padStart(2, '0');
  return `${yyyy}-${mm}-${dd}T${timeStr}:00`;
}

// ─── Helper: safe truncate to 255 chars ───────────────────────────────────────
function safe(str) {
  if (!str) return '';
  return String(str).slice(0, 255);
}

// 1. Added 'sensors' to the destructuring
const { actuators, warnings, notifications, recommendation, sensors } = input;
let suggestedActionsList = [];

// ─── 0.5. Check if actuators exist ────────────────────────────────────────────
// true if actuators array is missing or has 0 items
const noActuators = !actuators || actuators.length === 0;

// ─── 1. Loop through actuators ─────────────────────────────────────────────────
if (!noActuators) {
  for (const actuator of actuators) {
    const type = actuator.type;
    const classification = actuator.classification;

    // ── NEED-RE-EVALUATION ──
    if (classification === 'NEED-RE-EVALUATION') {
      entities.push({
        entity: `input_datetime.${type}_re_evaluation_start`,
        value: toFullDatetime(actuator.re_evaluation?.interval?.start ?? null)
      });
      entities.push({
        entity: `input_datetime.${type}_re_evaluation_end`,
        value: toFullDatetime(actuator.re_evaluation?.interval?.end ?? null)
      });
    }

    // ── TURN-ON ──
    else if (classification === 'TURN-ON') {
      entities.push({
        entity: `input_datetime.${type}_execute_at`,
        value: toFullDatetime(actuator.run?.execute_at ?? null)
      });
      entities.push({
        entity: `input_datetime.${type}_execute_until`,
        value: toFullDatetime(actuator.run?.execute_until ?? null)
      });
    }

    // ── recommended_action ──
    if (actuator.recommended_action) {
      const bullet = `• ${actuator.recommended_action}`;
      const currentLength = suggestedActionsList.join('\n').length;

      const addedLength = currentLength > 0 ? bullet.length + 1 : bullet.length;
      if (currentLength + addedLength <= 255) {
        suggestedActionsList.push(bullet);
      }
    }
  }
}

// ─── 2. Combined suggested actions entity ────────────────────────────────────
if (suggestedActionsList.length > 0) {
  entities.push({
    entity: 'input_text.suggested_actions',
    value: suggestedActionsList.join('\n')
  });
} else {
  // If no actuators exist, OR if none of them had a recommended_action
  entities.push({
    entity: 'input_text.suggested_actions',
    value: '' 
  });
}

// ─── 3. Warnings ───────────────────────────────────────────────────────────────
for (const warning of (warnings ?? [])) {
  // Original boolean state
  entities.push({
    entity: `input_boolean.${warning.name}`,
    value: warning.active
  });

  // NEW: Extra Info state (description || severity)
  const desc = warning.description ?? "";
  const severity = warning.severity ?? 0;
  entities.push({
    entity: `input_text.${warning.name}_extra_info`,
    value: safe(`${desc} || ${severity}`)
  });
}

// ─── 3.5. Sensors (NEW) ──────────────────────────────────────────────────────
for (const sensor of (sensors ?? [])) {
  // Map "air_humidity" to "humidity" to match your exact entity names
  const sensorName = sensor.type === 'air_humidity' ? 'humidity' : sensor.type;
  const desc = sensor.description ?? '';

  entities.push({
    entity: `input_text.${sensorName}_description`,
    value: safe(desc) // Keep safe() to prevent HA crashing on >255 chars
  });
}

// ─── 4. General recommendation ────────────────────────────────────────────────
// Only push to HA if actuators actually exist AND there is a recommendation text
if (!noActuators && recommendation) {
  entities.push({
    entity: 'input_text.general_recommendation',
    value: safe(recommendation)
  });
}

// ─── 5. Notifications ─────────────────────────────────────────────────────────
let notifText = '';
for (const note of (notifications ?? [])) {
  const line = `• ${note.title}: ${note.description}\n`;
  if ((notifText.length + line.length) > 255) break;
  notifText += line;
}
if (notifText) {
  entities.push({
    entity: 'input_text.notifications',
    value: notifText.trim()
  });
} else {
  entities.push({
    entity: 'input_text.notifications',
    value: ''
  });
}

// ─── 6. Return all entities for n8n ───────────────────────────────────────────
return entities.map(e => ({ json: e }));

const items = $input.all();

// Retrieve the 'adr' directly from node 1
const adr = $('data sender filter').first().json.adr;
const BASE_URL = `http://${adr}:8123/api/`;

const result = [];

for (const item of items) {
  const entityId = item.json.entity;
  const stateValue = item.json.value;
  const domain = entityId.split('.')[0]; 

  let finalUrl = '';
  let finalBody = {};

  // 1. USE SERVICES FOR DATETIMES (Preserves UI)
  if (domain === 'input_datetime') {
    if (!stateValue) continue; // Skip if no time is provided

    finalUrl = `${BASE_URL}services/input_datetime/set_datetime`;
    finalBody = {
      entity_id: entityId,
      // Format: YYYY-MM-DD HH:MM:SS
      datetime: String(stateValue).replace('T', ' ').substring(0, 19)
    };
  } 

  // 2. USE STATES FOR EVERYTHING ELSE (More reliable for text/booleans)
  else {
    finalUrl = `${BASE_URL}states/${entityId}`;

    let formattedState;
    if (typeof stateValue === 'boolean') {
      formattedState = stateValue ? 'on' : 'off';
    } else {
      formattedState = (stateValue === null || stateValue === undefined) ? '' : String(stateValue);
    }

    finalBody = {
      state: formattedState,
      attributes: {} // Optional, but helps keep the object structure clean
    };
  }

  result.push({
    json: {
      url: finalUrl,
      body: finalBody
    }
  });
}

return result;
